    MODE.configure(this, 4, 60, "RW", 0, 64'h0, 1, 1, 1);
  endfunction
  // WARL on the whole register: a write with an unsupported MODE (not Bare/Sv39) is dropped entirely
  virtual function void do_predict(uvm_reg_item rw, uvm_predict_e kind = UVM_PREDICT_DIRECT, uvm_reg_byte_en_t be = -1);
